Shader.FragmentShader:
void main() {
  float a = radians(Angle);
  vec2 d = vec2(cos(a), sin(a));
  vec2 p = (v_boxCoord - 0.5) * v_boxSize;
  float extent = dot(abs(d), v_boxSize) * 0.5;
  float t = clamp(dot(p, d) / max(extent, 1.0) * 0.5 + 0.5, 0.0, 1.0);
  vec3 c = t < 0.5 ? mix(Color0.rgb, Color1.rgb, t * 2.0) : mix(Color1.rgb, Color2.rgb, t * 2.0 - 1.0);
  FragColor = vec4(c, texture(u_texture, v_texcoord0).a * u_opacity);
}
